use std::fs;

pub fn rib_a() -> Result<Vec<String>, i32> {
    let root = "/app/dropwell";
    let rd = fs::read_dir(root).map_err(|_| 1)?;
    let mut out = Vec::new();
    for ent in rd.flatten() {
        let p = ent.path();
        if p.extension().and_then(|s| s.to_str()) != Some("clat") || !p.is_file() {
            continue;
        }
        let name = p.to_string_lossy().to_string();
        let bytes = match fs::read(&p) { Ok(b) => b, Err(_) => continue };
        if bytes.len() >= 12 && &bytes[..4] == b"CLAT" {
            out.push(name);
        }
    }
    out.sort();
    if out.is_empty() { Err(1) } else { Ok(out) }
}
