use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

fn mark_false() -> i32 {
    let _ = fs::create_dir_all("/app/kegbay");
    let _ = fs::write("/app/kegbay/MARK", "false");
    1
}

fn read_pairs() -> Vec<String> {
    let raw = fs::read_to_string("/app/kegbay/pairs.tmp").unwrap_or_default();
    let mut seen = HashSet::new();
    raw.lines().filter_map(|line| {
        let n = line.split('\t').next()?.to_string();
        if seen.insert(n.clone()) { Some(n) } else { None }
    }).collect()
}

fn last_good() -> HashMap<String, u32> {
    let mut out = HashMap::new();
    for line in fs::read_to_string("/app/tidearc/lastgood.rec").unwrap_or_default().lines() {
        let p: Vec<&str> = line.split('\t').collect();
        if p.len() >= 2 {
            if let Ok(seq) = p[0].parse::<u32>() { out.insert(p[1].to_string(), seq); }
        }
    }
    out
}

pub fn finish() -> i32 {
    let names = read_pairs();
    if names.is_empty() { return mark_false(); }
    let old = last_good();
    let mut known = Vec::new();
    let mut fresh = Vec::new();
    for path in names {
        let base = match Path::new(&path).file_name().and_then(|x| x.to_str()) {
            Some(x) => x.to_string(), None => return mark_false(),
        };
        if let Some(&seq) = old.get(&base) { known.push((seq, base, path)); }
        else { fresh.push((base, path)); }
    }
    known.sort_by(|a,b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    fresh.sort_by(|a,b| a.0.cmp(&b.0));
    let mut rows: Vec<(u32,String,String)> = known.into_iter().map(|(s,b,p)|(s,b,p)).collect();
    let mut seq = rows.iter().map(|r| r.0).max().unwrap_or(0) + 1;
    for (base,path) in fresh { rows.push((seq,base,path)); seq += 1; }
    let mut ribbon = String::new();
    for (seq, _, path) in &rows {
        let m = crate::parse::load(path);
        ribbon.push_str(&format!("{}\t{}\t{}\n", seq, path, crate::parse::guid_hex(&m.guid)));
    }
    if fs::create_dir_all("/app/kegbay").is_err() || fs::write("/app/kegbay/ribbon.txt", ribbon).is_err() {
        return mark_false();
    }
    0
}

fn valid_root(arg: Option<String>) -> bool {
    let requested = PathBuf::from(arg.unwrap_or_else(|| "/app/dropwell".to_string()));
    match (fs::canonicalize(requested), fs::canonicalize("/app/dropwell")) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    }
}

pub fn pour() -> i32 {
    if !valid_root(std::env::args().nth(2)) { return mark_false(); }
    let well = match crate::walk::rib_a() { Ok(v) if !v.is_empty() => v, _ => return mark_false() };
    let ribbon = fs::read_to_string("/app/kegbay/ribbon.txt").unwrap_or_default();
    let mut rows: Vec<(u32,String,String,String)> = Vec::new();
    let mut represented = HashSet::new();
    for line in ribbon.lines() {
        let p: Vec<&str> = line.split('\t').collect();
        if p.len() != 3 { return mark_false(); }
        let seq = match p[0].parse::<u32>() { Ok(x) => x, Err(_) => return mark_false() };
        let path = p[1];
        if !well.iter().any(|x| x == path) || !represented.insert(path.to_string()) { return mark_false(); }
        let name = match Path::new(path).file_name().and_then(|x| x.to_str()) { Some(x)=>x.to_string(), None=>return mark_false() };
        rows.push((seq, name, crate::sum::hex_file(path), p[2].to_string()));
    }
    if rows.len() != well.len() || rows.is_empty() || rows.iter().any(|r| r.2.len() != 64) { return mark_false(); }
    rows.sort_by_key(|r| r.0);
    let batches = (rows.len() + 2) / 3;
    let mut json = format!("{{\"batch_count\":{},\"entries\":[", batches);
    for (i,(seq,name,digest,guid)) in rows.iter().enumerate() {
        if i != 0 { json.push(','); }
        json.push_str(&format!("{{\"seq\":{},\"name\":\"{}\",\"digest\":\"{}\",\"guid\":\"{}\"}}",seq,name,digest,guid));
    }
    json.push_str("]}\n");
    let mut tsv = String::from("seq\tname\tdigest\tguid\n");
    for (seq,name,digest,guid) in &rows { tsv.push_str(&format!("{}\t{}\t{}\t{}\n",seq,name,digest,guid)); }
    if fs::write("/app/kegbay/upload.json",json).is_err() || fs::write("/app/kegbay/batch.tsv",tsv).is_err() || fs::write("/app/kegbay/MARK","ok").is_err() { return mark_false(); }
    0
}
